using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    [McpServerTool, Description("Fetches a post by ID from the external API.")]
    public static async Task<string> GetPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric ID of the post to retrieve.")] int id,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("api");
        var response = await client.GetAsync($"/posts/{id}", cancellationToken);

        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return json.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks an LLM to summarize the given text.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional target style, e.g. 'bullet-points' or 'one-paragraph'.")] string? style = null)
    {
        var styleHint = style is not null
            ? $" Use the following style: {style}."
            : string.Empty;

        return new GetPromptResult
        {
            Description = "Summarization prompt",
            Messages =
            [
                new PromptMessage
                {
                    Role = Role.User,
                    Content = new TextContentBlock
                    {
                        Text = $"Please summarize the following text concisely.{styleHint}\n\n{text}"
                    }
                }
            ]
        };
    }
}

